class TrieNode:
    def __init__(self):
        # Children: 26 slots, one for each lowercase a-z
        self.children = [None] * 26
        # How many times a word ends at this node
        self.end_count = 0
        # How many words pass through or end at this node (prefix count)
        self.prefix_count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def _char_to_index(self, ch):
        # helper to map char to index 0-25
        return ord(ch) - ord('a')

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            idx = self._char_to_index(ch)
            if not node.children[idx]:
                node.children[idx] = TrieNode()
            node = node.children[idx]
            node.prefix_count += 1
        node.end_count += 1

    def countWordsEqualTo(self, word: str) -> int:
        node = self.root
        for ch in word:
            idx = self._char_to_index(ch)
            if not node.children[idx]:
                return 0
            node = node.children[idx]
        return node.end_count

    def countWordsStartingWith(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            idx = self._char_to_index(ch)
            if not node.children[idx]:
                return 0
            node = node.children[idx]
        return node.prefix_count

    def erase(self, word: str) -> None:
        node = self.root
        stack = []
        for ch in word:
            idx = self._char_to_index(ch)
            stack.append((node, idx))
            node = node.children[idx]
        node.end_count -= 1
        # Decrement prefix_count for all nodes along word
        for parent, idx in stack:
            parent.children[idx].prefix_count -= 1
